const TEAM_COLORS = ["#FFC857", "#5FCB94", "#7FB2E5", "#EF6461"];

function TeamDrawSection({ occasion, players, isAdmin, drawTeams, clearTeams, setTeamGoalkeeper }) {
  const yesIds = Object.keys(occasion.responses || {}).filter((id) => occasion.responses[id] === "yes");
  const [numTeams, setNumTeams] = useState(yesIds.length > 12 ? 3 : 2);
  const teams = occasion.teams || [];
  const hasTeams = teams.length > 0;

  function playerById(id) {
    return players.find((p) => p.id === id);
  }

  if (yesIds.length < 4) return null;

  return (
    <div className="mt-5 pt-4" style={{ borderTop: `1px solid ${C.line}` }}>
      <div className="flex items-center gap-2 mb-3">
        <Shuffle size={18} color={C.accent} />
        <p className="font-semibold text-sm">Csapatbeosztás</p>
      </div>

      {isAdmin && (
        <div className="flex items-center gap-2 mb-3">
          <span className="text-xs" style={{ color: C.textMuted }}>Hány csapat legyen?</span>
          <div className="flex gap-1">
            {[2, 3, 4].map((n) => (
              <button
                key={n}
                onClick={() => setNumTeams(n)}
                style={{ background: numTeams === n ? C.accent : "transparent", border: `1px solid ${numTeams === n ? C.accent : C.line}`, color: numTeams === n ? C.bg : C.textMuted }}
                className="w-8 h-8 rounded-full text-xs font-semibold"
              >
                {n}
              </button>
            ))}
          </div>
          <button onClick={() => drawTeams(occasion.id, numTeams)} style={{ background: C.accent, color: C.bg }} className="ml-auto flex items-center gap-1 text-xs font-semibold px-3 py-2 rounded-full">
            <Shuffle size={14} /> {hasTeams ? "Újrasorsolás" : "Sorsolás"}
          </button>
        </div>
      )}

      {!hasTeams && !isAdmin && <p className="text-xs" style={{ color: C.textMuted }}>Az admin még nem sorsolta ki a csapatokat.</p>}

      {hasTeams && (
        <div className="grid grid-cols-1 gap-3" style={{ gridTemplateColumns: teams.length > 1 ? "repeat(auto-fit, minmax(130px, 1fr))" : "1fr" }}>
          {teams.map((team, i) => (
            <div key={i} style={{ background: C.bgCard, border: `1px solid ${TEAM_COLORS[i % TEAM_COLORS.length]}` }} className="rounded-xl p-3">
              <p style={{ color: TEAM_COLORS[i % TEAM_COLORS.length] }} className="font-display text-lg mb-2">
                {i + 1}. CSAPAT ({team.playerIds.length} fő)
              </p>
              <div className="space-y-1.5">
                {team.playerIds.map((id) => {
                  const p = playerById(id);
                  if (!p) return null;
                  const isGk = team.goalkeeperId === id;
                  return (
                    <div key={id} className="flex items-center justify-between">
                      <span className="text-xs flex items-center gap-1" style={{ color: C.text }}>
                        {p.name}
                        {isGk && <span title="Kapus">🧤</span>}
                      </span>
                      {isAdmin && (
                        <button
                          onClick={() => setTeamGoalkeeper(occasion.id, i, id)}
                          style={{ color: isGk ? C.accent : C.textMuted }}
                          className="text-[10px]"
                        >
                          {isGk ? "kapus ✓" : "kapus?"}
                        </button>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}

      {hasTeams && isAdmin && (
        <button onClick={() => clearTeams(occasion.id)} className="text-xs mt-3" style={{ color: C.textMuted }}>
          Beosztás törlése
        </button>
      )}
    </div>
  );
}

function MotmSection({ occasion, players, myPlayerId, chooseMyPlayer, castMotmVote }) {
  const [pickerOpen, setPickerOpen] = useState(false);
  const candidates = players.filter((p) => (occasion.responses || {})[p.id] === "yes");
  const votingOpen = isMotmVotingOpen(occasion);
  const votingClosed = isMotmVotingClosed(occasion);
  const tally = motmTally(occasion);
  const winner = motmWinner(occasion);
  const winnerPlayer = winner ? players.find((p) => p.id === winner.playerId) : null;
  const myVote = myPlayerId ? (occasion.motmVotes || {})[myPlayerId] : null;

  if (candidates.length === 0) return null;

  return (
    <div className="mt-5 pt-4" style={{ borderTop: `1px solid ${C.line}` }}>
      <div className="flex items-center gap-2 mb-3">
        <Trophy size={18} color={C.accent} />
        <p className="font-semibold text-sm">A hét embere szavazás</p>
      </div>

      {!myPlayerId && (votingOpen || votingClosed) && (
        <div className="mb-3">
          <button onClick={() => setPickerOpen(!pickerOpen)} style={{ background: C.bgElevated, border: `1px solid ${C.line}`, color: C.textMuted }} className="text-xs px-3 py-2 rounded-lg font-semibold">
            Ki vagy te? Válaszd ki, hogy tudj szavazni
          </button>
          {pickerOpen && (
            <div className="flex flex-wrap gap-2 mt-2">
              {players.filter((p) => p.isActive !== false).map((p) => (
                <button key={p.id} onClick={() => { chooseMyPlayer(p.id); setPickerOpen(false); }} style={{ background: C.bgCard, border: `1px solid ${C.line}`, color: C.text }} className="text-xs px-2.5 py-1.5 rounded-full">
                  {p.name}
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {votingOpen && (
        <>
          <p className="text-xs mb-2" style={{ color: C.textMuted }}>
            Szavazz, ki volt a meccs embere! A szavazás az alkalom végét követő 24 óráig tart. Az eredmény csak a
            szavazás lezárása után derül ki.
            {myPlayerId && <> Te mint <b>{players.find((p) => p.id === myPlayerId)?.name}</b> szavazol.</>}
          </p>
          <div className="flex flex-wrap gap-2">
            {candidates.map((p) => {
              const voted = myVote === p.id;
              const disabled = !myPlayerId || myPlayerId === p.id;
              return (
                <button
                  key={p.id}
                  disabled={disabled}
                  onClick={() => castMotmVote(occasion.id, p.id)}
                  style={{
                    background: voted ? C.accent : C.bgCard,
                    border: `1px solid ${voted ? C.accent : C.line}`,
                    color: voted ? C.bg : C.text,
                    opacity: disabled && myPlayerId !== p.id ? 0.5 : 1,
                  }}
                  className="flex items-center gap-2 text-xs font-semibold px-3 py-2 rounded-full"
                >
                  <Avatar player={p} size={22} />
                  {p.name}
                  {voted ? <Check size={14} /> : null}
                </button>
              );
            })}
          </div>
        </>
      )}

      {votingClosed && winnerPlayer && (
        <>
          <PlayerOfTheMatchCard occasion={occasion} player={winnerPlayer} votes={winner.votes} />
          <div className="mt-4 space-y-1.5">
            <p className="text-xs font-semibold" style={{ color: C.textMuted }}>Végeredmény:</p>
            {candidates
              .map((p) => ({ ...p, count: tally[p.id] || 0 }))
              .filter((p) => p.count > 0)
              .sort((a, b) => b.count - a.count)
              .map((p) => (
                <div key={p.id} className="flex items-center justify-between text-xs">
                  <span style={{ color: C.text }}>{p.name}</span>
                  <span style={{ color: C.textMuted }}>{p.count} szavazat</span>
                </div>
              ))}
          </div>
        </>
      )}
      {votingClosed && !winnerPlayer && (
        <p className="text-xs" style={{ color: C.textMuted }}>Erre az alkalomra nem érkezett szavazat.</p>
      )}
    </div>
  );
}

