function fmtDateCard(d) {
  const date = new Date(d);
  const month = date.toLocaleDateString("hu-HU", { month: "long" });
  const monthCap = month.charAt(0).toUpperCase() + month.slice(1);
  const weekday = date.toLocaleDateString("hu-HU", { weekday: "long" });
  return `${monthCap} ${date.getDate()}. ${weekday}`;
}

function PlayerOfTheMatchCard({ occasion, player, votes }) {
  const cardRef = useRef(null);
  const [downloading, setDownloading] = useState(false);

  async function handleDownload() {
    if (!cardRef.current) return;
    setDownloading(true);
    try {
      const dataUrl = await toPng(cardRef.current, { pixelRatio: 2 });
      const link = document.createElement("a");
      link.download = `${player.name.replace(/\s+/g, "_")}_a_het_focistaja.png`;
      link.href = dataUrl;
      link.click();
    } catch (e) {
      console.error(e);
    }
    setDownloading(false);
  }

  // A nevet a hosszától függően kicsit kisebbre vesszük, hogy biztosan kiférjen a sávban
  const nameFontSize = player.name.length > 20 ? 18 : player.name.length > 16 ? 22 : player.name.length > 12 ? 26 : 32;

  return (
    <div className="mt-3">
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&display=swap');`}</style>
      <div className="flex justify-center">
        <div
          ref={cardRef}
          style={{
            position: "relative",
            width: 300,
            aspectRatio: "1060 / 1484",
            borderRadius: 14,
            overflow: "hidden",
          }}
        >
          <img src={CARD_TEMPLATE} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />

          {player.photo && (
            <div
              style={{
                position: "absolute",
                left: "14.15%",
                top: "36.05%",
                width: "71.7%",
                height: "44.95%",
                overflow: "hidden",
              }}
            >
              <img src={player.photo} alt={player.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
            </div>
          )}

          <div
            style={{
              position: "absolute",
              left: "14.9%",
              top: "81.7%",
              width: "70.3%",
              height: "9.1%",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <span
              style={{
                fontFamily: "'Bebas Neue', sans-serif",
                color: "#F2E7D3",
                fontSize: nameFontSize,
                textAlign: "center",
                textTransform: "uppercase",
                lineHeight: 1,
                letterSpacing: "0.01em",
                whiteSpace: "nowrap",
              }}
            >
              {player.name}
            </span>
          </div>
        </div>
      </div>
      <p className="text-center text-xs mt-2" style={{ color: C.textMuted }}>
        {fmtDateCard(occasion.date)} · {votes} szavazattal
      </p>
      <div className="flex justify-center mt-2">
        <button onClick={handleDownload} disabled={downloading} style={{ background: C.accent, color: C.bg }} className="text-xs font-semibold px-4 py-2 rounded-full">
          {downloading ? "Készül..." : "Kártya letöltése képként"}
        </button>
      </div>
    </div>
  );
}
